import { describe, expect, it } from 'vitest'
import { fitTheilSen } from '../../src/core/stats/series'
import goldens from '../goldens/theil_sen.json'

// Scoped parity with analyses.methods._theil_sen_estimator, generated by
// scripts/gen_goldens.py. Full Python outputs are retained in the fixture for
// audit, but this suite verifies only slope, reason, and R² on shared domains.
// Known differences (characterized in core/stats/theilSen.test.ts):
// - Web accepts two distinct dates; Python requires at least three points.
// - Web intercept is median(y - slope*x); Python uses SciPy's default separate
//   medians, median(y) - slope*median(x), which can give a different intercept.
// - Web CI is always NaN; Python computes non-parametric slope confidence bounds.
// Consequently, passing these tests does not establish full estimator parity.
describe('fitTheilSen Python slope/reason/R² parity on shared input domain', () => {
  it.each(goldens)('$name', (g) => {
    const points = g.xYears.map((year, i) => ({
      date: new Date(Date.UTC(2000, 0, 1) + year * 365.25 * 86_400_000),
      value: g.values[i],
    }))
    const fit = fitTheilSen(points)
    expect(fit.reason).toBe(g.reason)
    if (g.slope === null) expect(fit.slope).toBeNaN()
    else expect(fit.slope).toBeCloseTo(g.slope, 10)
    if (g.r2 === null) expect(fit.r2).toBeNaN()
    else expect(fit.r2).toBeCloseTo(g.r2, 10)
  })
})
